"""
    Implements signed right-shift.
    See: http://stackoverflow.com/a/5833119/15677
    """
def rshift(val: Any, n: Any) -> object {
    return ((val % 4294967296) >> n);
}

"""Returns the nth Fibonacci number in the Fibonacci sequence.

  The Fibonacci numbers are the numbers in the Fibonacci sequence, defined by
  the equation and seed values:

  F(n) = F(n - 1) + F(n - 2)

  F(0) = 0
  F(1) = 1

  * O(2^n) time complexity
  * O(n) space complexity

  Args:
    number: An integer.
  """
def fibonacci_recursive(number: Any) -> object {
    if ((number == 0) or (number == 1)) {
        return number;
    }
    return (fibonacci_recursive((number - 1)) + fibonacci_recursive((number - 2)));
}

