""""Process a text line the pose format
        # timestamp x y z roll pitch yaw id
        input: line
        output: float x, float y, string id, float timeStamp"""
def processPoseLine(line: Any) -> object {
    spaceCount = 0;
    x = "";
    y = "";
    id = "";
    timeStamp = "";
    for char in line {
        if (char == ",") {
            char = ".";
        }
        if (char == " ") {
            spaceCount += 1;
        } elif (spaceCount == 0) {
            timeStamp += char;
        } elif (spaceCount == 1) {
            x += char;
        } elif (spaceCount == 2) {
            y += char;
        } elif ((spaceCount == 7) and (char != "\n")) {
            id += char;
        }
    }
    fx = float(x);
    fy = float(y);
    timeStamp = float(timeStamp);
    return (fx, fy, id, timeStamp);
}

